import json
import time
from pathlib import Path
from typing import Dict, Any

class HallmarkTokensCompiler:
    """
    Compiles W3C Design Tokens JSON to CSS custom properties.
    """
    def __init__(self, tokens_path: str = "integrations/hallmark_design/tokens.json"):
        self.tokens_path = Path(tokens_path)

    def load_tokens(self) -> Dict[str, Any]:
        with open(self.tokens_path, "r", encoding="utf-8") as f:
            return json.load(f)

    def compile_to_css(self) -> str:
        tokens = self.load_tokens()
        lines = [
            "/* Generated by HallmarkTokensCompiler - DO NOT EDIT DIRECTLY */",
            ":root {"
        ]
        
        def walk(prefix: str, obj: Dict[str, Any]):
            for key, val in obj.items():
                if key.startswith("$"):
                    continue
                if isinstance(val, dict):
                    if "value" in val:
                        var_name = f"--{prefix}-{key.replace('_', '-')}" if prefix else f"--{key.replace('_', '-')}"
                        lines.append(f"  {var_name}: {val['value']};")
                    else:
                        sub_prefix = f"{prefix}-{key.replace('_', '-')}" if prefix else key.replace('_', '-')
                        walk(sub_prefix, val)

        walk("cbt", tokens.get("color", {}))
        lines.append("}\n")
        return "\n".join(lines)

def benchmark_compiler():
    compiler = HallmarkTokensCompiler()
    t0 = time.perf_counter()
    css = compiler.compile_to_css()
    t1 = time.perf_counter()
    latency_ms = (t1 - t0) * 1000
    print(f"[BENCHMARK] Hallmark token compilation latency: {latency_ms:.3f}ms")
    print(f"Generated CSS lines: {len(css.splitlines())}")
    return latency_ms

if __name__ == "__main__":
    benchmark_compiler()
